import {ToolRegistry} from './registry.js';
import {jest} from '@jest/globals';
import {log} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property and never calls the executor ([validated by specs/hal-engine-tool-input-validation/spec.md#1])', async () => {
    const registry = new ToolRegistry();
    let executorCalled = false;

    registry.register(
      {
        name: 'test-tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'}
          },
          required: ['location']
        }
      },
      async (input) => {
        executorCalled = true;
        return 'success';
      }
    );

    const result = await registry.execute('test-tool', {});

    expect(executorCalled).toBe(false);
    expect(result).toEqual({
      result: expect.stringContaining('location')
    });
  });

  it('valid input with an unlisted extra property is passed through to the executor unchanged exactly once ([validated by specs/hal-engine-tool-input-validation/spec.md#3])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async (input: any) => 'success');

    registry.register(
      {
        name: 'test-tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'}
          },
          required: ['location']
        }
      },
      executor as any
    );

    const input = {location: 'paris', extra: 123};
    await registry.execute('test-tool', input);

    expect(executor).toHaveBeenCalledTimes(1);
    expect(executor).toHaveBeenCalledWith(input, undefined);
  });

  it('rejects a wrong-typed field with a message naming the field path and expected type without offending value ([validated by specs/hal-engine-tool-input-validation/spec.md#2])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'success');

    registry.register(
      {
        name: 'test-tool',
        description: 'Test tool',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'}
          }
        }
      },
      executor
    );

    const result = await registry.execute('test-tool', {location: 123}) as any;

    expect(executor).not.toHaveBeenCalled();
    expect(result.result).toContain('location');
    expect(result.result).toContain('string');
    expect(result.result).not.toContain('123');
  });

  it('throws at register time for an uncompilable schema naming the tool ([validated by specs/hal-engine-tool-input-validation/spec.md#5])', () => {
    const registry = new ToolRegistry();
    expect(() => {
      registry.register({
        name: 'bad-tool',
        description: 'Bad tool',
        inputSchema: {
          type: 'invalid-type'
        }
      } as any, async () => 'success');
    }).toThrow(/bad-tool/);
  });

  it('validates a function-valued tool definition against the schema current at that call ([validated by specs/hal-engine-tool-input-validation/spec.md#7])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'success');

    let schemaType = 'string';
    const source = () => ({
      name: 'dynamic-tool',
      description: 'Dynamic tool',
      inputSchema: {
        type: 'object',
        properties: {
          value: {type: schemaType}
        }
      }
    } as ToolDefinition);

    registry.register(source, executor);

    const result1 = await registry.execute('dynamic-tool', {value: 'test'}) as any;
    expect(result1.result).toBeUndefined(); // success

    schemaType = 'number';
    const result2 = await registry.execute('dynamic-tool', {value: 'test'}) as any;
    expect(result2.result).toBeDefined(); // fails validation
    expect(result2.result).toContain('value');
  });

  it('compiles a static tool schema once across multiple execute calls ([validated by specs/hal-engine-tool-input-validation/spec.md#6])', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'success');

    let getterCalled = 0;
    const def = {
      name: 'static-tool',
      description: 'Static tool',
    } as ToolDefinition;

    Object.defineProperty(def, 'inputSchema', {
      get: () => {
        getterCalled++;
        return {type: 'object', properties: {val: {type: 'string'}}};
      }
    });

    registry.register(def, executor);

    for (let i = 0; i < 10; i++) {
      await registry.execute('static-tool', {val: 'test'});
    }

    expect(getterCalled).toBe(1); // Once at register time
  });

  it('throws Unknown tool for an unregistered name ([validated by specs/hal-engine-tool-input-validation/spec.md#4])', async () => {
    const registry = new ToolRegistry();
    await expect(registry.execute('unknown-tool', {})).rejects.toThrow('Unknown tool: unknown-tool');
  });
});

